mapper.select:
select e.*,s.realname as staffname,o.orgname as deptname from TBL_EVALUATIONINTERVIEW e left join tbl_staff s on s.staffid=e.staffid left join tbl_organization o on o.orgid=e.dept where 1=1
and e.module LIKE concat(concat('%',#{param.module}),'%')
and e.content LIKE concat(concat('%',#{param.content}),'%')
and e.unit=#{param.unit}
${sql}
order by id desc
